        for (int[] p : prerequisites) prereqs.get(p[0]).add(p[1]);
        state = new int[numCourses];
        order = new int[numCourses];
        idx = 0;
        for (int c = 0; c < numCourses; c++) {
            if (!dfs(c)) return new int[0];
        }
        return order;
    }

    private boolean dfs(int c) {
        if (state[c] == 1) return false;
        if (state[c] == 2) return true;
        state[c] = 1;
        for (int p : prereqs.get(c)) if (!dfs(p)) return false;
        state[c] = 2;
        order[idx++] = c;
        return true;
    }
}

